-- Como los ids se han puesto a mano, se sincronizan las secuencias
SELECT setval('usuario_id_seq', (SELECT max(id) FROM usuario));
SELECT setval('cliente_id_seq', (SELECT max(id) FROM cliente));
SELECT setval('equipo_id_seq', (SELECT max(id) FROM equipo));
SELECT setval('reparacion_id_seq', (SELECT max(id) FROM reparacion));
