INSERT INTO reparacion (id, codigo, equipo_id, tecnico_id, averia_descrita, diagnostico, estado, presupuesto, presupuesto_aceptado, precio_final, fecha_entrada, fecha_listo, fecha_entrega) VALUES
  (1, 'FX-2026-00001', 1, 2, 'Se derramó café sobre el teclado y ahora no enciende.', 'Placa con corrosión en la zona de alimentación. Limpieza por ultrasonidos y sustitución de teclado.', 'ENTREGADO', 145, TRUE, 145, now() - interval '4084 hours', now() - interval '4084 hours' + interval '72 hours', now() - interval '4084 hours' + interval '144 hours'),
  (2, 'FX-2026-00002', 2, 3, 'Va muy lento, tarda varios minutos en arrancar.', 'Disco mecánico con sectores dañados. Cambio a SSD 500 GB y clonado del sistema.', 'ENTREGADO', 89, TRUE, 89, now() - interval '3845 hours', now() - interval '3845 hours' + interval '30 hours', now() - interval '3845 hours' + interval '72 hours'),
  (3, 'FX-2026-00003', 3, 4, 'Se apaga solo cuando juego a los 10-15 minutos.', 'Temperaturas de CPU a 95 °C. Limpieza completa y cambio de pasta térmica.', 'ENTREGADO', 45, TRUE, 45, now() - interval '3606 hours', now() - interval '3606 hours' + interval '39 hours', now() - interval '3606 hours' + interval '48 hours'),
  (4, 'FX-2026-00004', 4, 3, 'Pantalla rota tras una caída.', 'Cristal y panel OLED dañados. Sustitución de pantalla completa.', 'ENTREGADO', 189, TRUE, 189, now() - interval '3367 hours', now() - interval '3367 hours' + interval '66 hours', now() - interval '3367 hours' + interval '96 hours'),
  (5, 'FX-2026-00005', 5, 2, 'Salen anuncios en el navegador y se abren páginas solas.', 'Adware y extensiones maliciosas. Limpieza y revisión de seguridad.', 'ENTREGADO', 35, TRUE, 35, now() - interval '3080 hours', now() - interval '3080 hours' + interval '21 hours', now() - interval '3080 hours' + interval '24 hours'),
  (6, 'FX-2026-00006', 6, 4, 'No carga, hay que mover el cable para que cargue.', 'Conector USB-C desgastado. Sustitución del puerto de carga.', 'ENTREGADO', 59, TRUE, 59, now() - interval '2769 hours', now() - interval '2769 hours' + interval '59 hours', now() - interval '2769 hours' + interval '72 hours'),
  (7, 'FX-2026-00007', 7, 2, 'El ventilador hace mucho ruido.', 'Ventilador con holgura en el eje. Sustitución de ventilador y limpieza.', 'ENTREGADO', 65, TRUE, 65, now() - interval '2434 hours', now() - interval '2434 hours' + interval '113 hours', now() - interval '2434 hours' + interval '120 hours'),
  (8, 'FX-2026-00008', 8, 3, 'La batería dura menos de una hora.', 'Batería al 61 % de salud. Presupuesto de cambio de batería.', 'ENTREGADO', 99, FALSE, 15, now() - interval '2211 hours', now() - interval '2211 hours' + interval '91 hours', now() - interval '2211 hours' + interval '96 hours'),
  (9, 'FX-2026-00009', 9, 4, 'Quiere instalar Windows 11 y pasar sus fotos del equipo antiguo.', 'Instalación limpia de Windows 11, drivers y migración de datos.', 'ENTREGADO', 60, TRUE, 60, now() - interval '1924 hours', now() - interval '1924 hours' + interval '23 hours', now() - interval '1924 hours' + interval '48 hours'),
  (10, 'FX-2026-00010', 10, 2, 'No da imagen, se encienden los ventiladores pero la pantalla queda en negro.', 'Módulo de RAM defectuoso. Sustitución por módulo de 8 GB.', 'ENTREGADO', 55, TRUE, 55, now() - interval '1589 hours', now() - interval '1589 hours' + interval '50 hours', now() - interval '1589 hours' + interval '72 hours'),
  (11, 'FX-2026-00011', 11, 3, 'Bisagra rota, la pantalla no se sujeta.', 'Bisagra izquierda partida y anclaje de la carcasa dañado.', 'ENTREGADO', 75, TRUE, 75, now() - interval '1254 hours', now() - interval '1254 hours' + interval '156 hours', now() - interval '1254 hours' + interval '168 hours'),
  (12, 'FX-2026-00012', 12, 4, 'Revisión y mantenimiento antes de dárselo a un nuevo empleado.', 'Limpieza, actualización de BIOS y reinstalación del sistema.', 'ENTREGADO', 50, TRUE, 50, now() - interval '967 hours', now() - interval '967 hours' + interval '36 hours', now() - interval '967 hours' + interval '48 hours'),
  (13, 'FX-2026-00013', 13, 2, 'El móvil se ha mojado en la playa.', 'Daños por líquido en placa. Limpieza; no se garantiza la recuperación.', 'ENTREGADO', 70, TRUE, 70, now() - interval '728 hours', now() - interval '728 hours' + interval '72 hours', now() - interval '728 hours' + interval '120 hours'),
  (14, 'FX-2026-00014', 14, 3, 'No le funciona el altavoz en las llamadas.', 'Altavoz auricular obstruido y dañado. Sustitución.', 'LISTO', 49, TRUE, 49, now() - interval '297 hours', now() - interval '297 hours' + interval '96 hours', NULL),
  (15, 'FX-2026-00015', 15, 4, 'El teclado tiene varias teclas que no responden.', 'Teclado dañado. Sustitución del top case completo.', 'ESPERANDO_APROBACION', 229, NULL, NULL, now() - interval '154 hours', NULL, NULL),
  (16, 'FX-2026-00016', 2, 3, 'La tecla de encendido se ha hundido.', 'Pulsador de encendido roto en el top case.', 'EN_REPARACION', 40, TRUE, NULL, now() - interval '123 hours', NULL, NULL),
  (17, 'FX-2026-00017', 5, 2, 'Se ha vuelto a llenar de publicidad.', 'Reinfección desde una extensión sincronizada con el navegador.', 'EN_REPARACION', 35, TRUE, NULL, now() - interval '76 hours', NULL, NULL),
  (18, 'FX-2026-00018', 7, 2, 'Pantalla con una línea vertical rosa.', NULL, 'DIAGNOSTICO', NULL, NULL, NULL, now() - interval '53 hours', NULL, NULL),
  (19, 'FX-2026-00019', 3, 4, 'Quiere ampliar a 32 GB de RAM y un segundo SSD.', NULL, 'DIAGNOSTICO', NULL, NULL, NULL, now() - interval '30 hours', NULL, NULL),
  (20, 'FX-2026-00020', 9, NULL, 'No se conecta al wifi después de una actualización.', NULL, 'RECIBIDO', NULL, NULL, NULL, now() - interval '7 hours', NULL, NULL),
  (21, 'FX-2026-00021', 6, NULL, 'La cámara trasera no enfoca.', NULL, 'RECIBIDO', NULL, NULL, NULL, now() - interval '8 hours', NULL, NULL);
